"""Text-to-SQL harness: draft, execute, and one targeted repair pass.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}      (hint is BIRD's evidence; "" for Spider)
  env.chat(messages, max_tokens=None) -> str     policy calls capped per task (env.max_calls)
  env.schema(db_id) -> str                       CREATE statements of the database
  env.execute(sql, max_rows=20) -> dict          read-only run: {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str                 column descriptions if the dataset ships them, else ""
  env.prompt(name) -> str                        text of a file in this harness
  env.config -> dict                             parsed config.json
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    return (text or "").strip().rstrip(";").strip()


def _fmt_rows(res):
    lines = []
    for row in (res.get("rows") or [])[:5]:
        lines.append(str(row))
    return "\n".join(lines)


def _needs_repair(res):
    if res is None:
        return False
    if not res.get("ok"):
        return True
    # An empty result is usually a wrong literal, a wrong join key or a
    # NULL-unsafe negation rather than a genuinely empty answer.
    return int(res.get("n_rows") or 0) == 0


def _repair_user(task, schema, sql, res):
    if res.get("ok"):
        outcome = (
            "It executed successfully but returned ZERO rows. For a question like this an "
            "empty answer almost always means the query is wrong, not that the data is missing."
        )
    else:
        outcome = "It FAILED with this SQLite error:\n" + str(res.get("error") or "")
    parts = [
        f"Database: {task['db_id']}\n\nSchema:\n{schema}",
        f"\nQuestion: {task['question']}",
    ]
    if task.get("hint"):
        parts.append(f"\nHint: {task['hint']}")
    parts.append(f"\nYour previous query was:\n```sql\n{sql}\n```")
    parts.append("\n" + outcome)
    parts.append(
        "\nWrite a corrected query. Do NOT repeat the previous query unchanged. Check, in order:\n"
        "1. String literals: the wording in the question may differ from the stored value in case, "
        "spelling, punctuation or surrounding whitespace. Prefer a tolerant match such as "
        "col LIKE '%key word%' (or lower(col) LIKE '%key word%') over col = 'exact phrase', and "
        "match on the distinctive words rather than the whole quoted phrase.\n"
        "2. Category/label filters: the stored label may be longer or shorter than the question's "
        "word (e.g. a degree, status or type name). Use LIKE on the label column instead of equality.\n"
        "3. Negation / 'does not have any': NOT IN (subquery) returns nothing if the subquery can "
        "produce NULL. Use NOT EXISTS with an explicit correlation, or LEFT JOIN ... IS NULL.\n"
        "4. Join keys: confirm you joined on the columns the schema actually declares, and that "
        "every intermediate table needed to connect the two ends is present.\n"
        "5. Projection: if the question asks which entities qualify without naming specific "
        "attributes, select the entity's columns (t.*) rather than just its name.\n"
        "Return only the corrected query in a single ```sql code block."
    )
    return "".join(parts)


def solve(task, env):
    cfg = env.config or {}
    max_tokens = cfg.get("max_tokens", 800)
    schema = env.schema(task["db_id"])
    user = f"Database: {task['db_id']}\n\nSchema:\n{schema}\n\nQuestion: {task['question']}"
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += "\n\nColumn notes:\n" + desc.strip()[:2000]
    if task.get("hint"):
        user += f"\nHint: {task['hint']}"

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=max_tokens)
    sql = extract_sql(reply)
    if not sql:
        return {"sql": sql}

    budget = getattr(env, "max_calls", 2) or 2
    if budget < 2 or not cfg.get("verify", True):
        return {"sql": sql}

    try:
        res = env.execute(sql, max_rows=20)
    except Exception:
        return {"sql": sql}
    if not _needs_repair(res):
        return {"sql": sql}

    messages = messages + [
        {"role": "assistant", "content": reply},
        {"role": "user", "content": _repair_user(task, schema, sql, res)},
    ]
    try:
        reply2 = env.chat(messages, max_tokens=max_tokens)
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2 or sql2 == sql:
        return {"sql": sql}

    try:
        res2 = env.execute(sql2, max_rows=20)
    except Exception:
        return {"sql": sql}
    # Keep the repair only if it runs and is not still empty while the original
    # at least produced something usable.
    if not res2.get("ok"):
        return {"sql": sql}
    if int(res2.get("n_rows") or 0) == 0 and int(res.get("n_rows") or 0) > 0:
        return {"sql": sql}
    return {"sql": sql2}

